import { createController } from './controller.js';
// Each post must deliver to the topic supplied at that call, even if later posts precede delivery.
export function createHost(schedule, deliver) {
  const controller = createController(schedule, deliver);
  return { post(topic, text) { controller.select(topic); controller.queue(text); } };
}

